s=s.replace('</head>',css+'</head>',1)

old_pat=r"function renderProducts\(\)\{const g=document\.getElementById\('productGrid'\);g\.innerHTML=products\.map\(p=>`.*?\|\|'<p>No hay productos en esta selección\.</p>'\}"
new_func=r'''function renderProducts(){const card=p=>`<article class="product" onclick="openProductDetail('${p.id}')">${p.hasDiscount?`<span class="offerBadge">-${Number(p.discountPct||0)}%</span>`:''}<button class="heart" onclick="event.stopPropagation()">♡</button><div class="photo" style="background-image:url('${(p.image||'').replace(/'/g,'')}')"></div><div class="pcat">${p.category}</div><h3>${p.title}</h3><div class="pref">Ref. ${p.ref}</div><div class="pfoot"><div><div>${p.hasDiscount?`<span class="oldPrice">${eur(p.regularPrice)}</span>`:''}<span class="price">${eur(p.salePrice??p.price)}</span></div><div class="stock">● Disponible bajo pedido</div></div><button class="add" onclick="event.stopPropagation();addToCart('${p.id}')">🛒</button></div></article>`;const g=document.getElementById('productGrid'),o=document.getElementById('offerGrid');const offers=products.filter(p=>p.hasDiscount||p.onOffer);const rec=products.filter(p=>!p.hasDiscount).slice(0,6);if(o)o.innerHTML=(offers.length?offers.slice(0,6):products.slice(0,6)).map(card).join('')||'<p>No hay ofertas disponibles.</p>';if(g)g.innerHTML=(rec.length?rec:products.slice(0,6)).map(card).join('')||'<p>No hay productos en esta selección.</p>'}'''
s2,n=re.subn(old_pat,new_func,s,count=1,flags=re.S)
if n!=1:
    raise SystemExit('renderProducts patch failed')
s=s2
p.write_text(s,encoding='utf-8')
print('patched template v5')
